// Area membership is administrative; sign-to-arrival matching is still proximity-based.
export const zoneGroupKey = zone => zone.shopAreaId ? `area:${zone.shopAreaId}` : `warp:${zone.id}`;
export const zoneGroupName = zone => zone.shopAreaName || zone.warpName;

export function shopZone(shop, zones) {
  const local = zones.filter(z => z.serverKey === shop.serverKey && z.dimensionKey === shop.dimensionKey);
  const explicit = local.find(z => shop.warpZoneId && z.id === shop.warpZoneId);
  if (explicit) return explicit;
  const named = local.filter(z => shop.warpName && z.warpName.toLowerCase() === shop.warpName.toLowerCase());
  if (named.length === 1) return named[0];
  const candidates = local.map(zone => ({ zone, distance: Math.hypot(shop.x - zone.centerX, shop.z - zone.centerZ) }))
    .filter(({zone, distance}) => Math.abs(shop.y - zone.centerY) <= 24 && distance <= zone.radius)
    .sort((a, b) => a.distance - b.distance || a.zone.id.localeCompare(b.zone.id));
  if (candidates.length > 1 && Math.abs(candidates[0].distance - candidates[1].distance) < 1
    && zoneGroupKey(candidates[0].zone) !== zoneGroupKey(candidates[1].zone)) return null;
  return candidates[0]?.zone || null;
}

export function decorateShopArea(shop, zones) {
  const zone = shopZone(shop, zones);
  return { ...shop, warpName: zone?.warpName || shop.warpName || null,
    shopAreaName: zone?.shopAreaName || null,
    shopGroupKey: zone ? zoneGroupKey(zone) : shop.warpName ? `unlinked:${shop.serverKey}:${shop.dimensionKey}:${shop.warpName}` : null };
}

export function shopAreaOptions(zones, shops) {
  const options = new Map(zones.map(z => [zoneGroupKey(z), zoneGroupName(z)]));
  shops.forEach(s => { if (s.shopGroupKey && !options.has(s.shopGroupKey)) options.set(s.shopGroupKey, s.shopAreaName || s.warpName); });
  return [...options].map(([value, label]) => ({ value, label })).sort((a, b) => a.label.localeCompare(b.label));
}
